function getJavaHelper(_java) {
    if (_java && typeof _java.ajax === 'function') return _java;
    if (typeof this !== 'undefined' && this && this.java && typeof this.java.ajax === 'function') return this.java;
    if (typeof $java !== 'undefined' && $java && typeof $java.ajax === 'function') return $java;
