function Num(e) {
    e = String(e || 0);
    return e.length > 8 ? (e.substring(0, e.length - 8) + "亿") : (e.length > 4 ? (e.substring(0, e.length - 4) + "万") : e);
}

function toApiUrl(url) {
    var str = String(url || "");
    var m = str.match(/(?:album|photos?|chapter)[/?](\d+)/i) || str.match(/id=(\d+)/i) || str.match(/^(?:jm)?(\d+)$/i);
    if (m) {
        return apiDomains[0] + "/album?id=" + m[1];
    }
    return str;
}

function Getdata(url, postBody, _java) {
    var j = getJavaHelper(_java);
    var ts = String(Math.floor(Date.now() / 1000));
    var headers = {
        "User-Agent": "Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/127.0.0.0 Mobile Safari/537.36 EdgA/127.0.0.0",
        "tokenparam": ts + "," + JMversion
    };

    var opt = {
        "method": postBody ? "POST" : "GET",
        "headers": headers
    };
    if (postBody) {
        opt.body = postBody;
    }

    var result = "";
    var candidateUrls = [];
    if (url.indexOf("http") === 0) {
        candidateUrls.push(url);
        for (var d = 1; d < apiDomains.length; d++) {
            var altUrl = url.replace(/https?:\/\/[^\/]+/, apiDomains[d]);
            if (altUrl !== url) candidateUrls.push(altUrl);
        }
    } else {
        for (var i = 0; i < apiDomains.length; i++) {
            candidateUrls.push(apiDomains[i] + (url.indexOf("/") === 0 ? "" : "/") + url);
        }
    }

    for (var u = 0; u < candidateUrls.length; u++) {
        try {
            var fullReq = candidateUrls[u] + "," + JSON.stringify(opt);
            if (j && typeof j.ajax === 'function') {
                result = j.ajax(fullReq);
            }
            if (result && result.length > 10) {
                break;
            }
        } catch(err) {}
    }

    if (!result) return "{}";

    try {
        var json = JSON.parse(result);
        if (json.code === 200 && json.data) {
            if (j && typeof j.md5Encode === 'function' && typeof j.aesBase64DecodeToString === 'function') {
                var sign = j.md5Encode(ts + data_secret);
                var dec = j.aesBase64DecodeToString(json.data, sign, "AES/ECB/PKCS7Padding", "");
                return dec || "{}";
            }
        }
    } catch(e) {}

    return result;
}

function formatComments(aid, maxPages, _java) {
    var j = getJavaHelper(_java);
    if (!maxPages) maxPages = 3;
    var commentsList = [];
    var totalCount = 0;

    for (var page = 1; page <= maxPages; page++) {
        var forumUrl = apiDomains[0] + "/forum?page=" + page + "&mode=manhua&aid=" + aid;
        var res = Getdata(forumUrl, null, j);
        if (!res) break;
        try {
            var dataObj = JSON.parse(res);
            totalCount = dataObj.total || 0;
            var pList = dataObj.list || [];
            if (!pList.length) break;

            if (commentsList.length > 9 && pList[0].content === commentsList[commentsList.length - 10].content) {
                break;
            }

            commentsList = commentsList.concat(pList);
            if (pList.length < 10) break;
        } catch(e) {
            break;
        }
    }

    if (commentsList.length === 0) {
        return "━━━━━━━━━━━━━━━━━━━━━\n☕【书友评论】 暂无书友评论。";
    }

    var output = [];
    for (var i = 0; i < commentsList.length; i++) {
        var item = commentsList[i];
        if (!item) continue;

        var timeStr = item.addtime ? "[" + item.addtime + "]" : "";
        var level = (item.expinfo && item.expinfo.level) ? item.expinfo.level : 1;
        var genderIcon = item.gender === "Male" ? " ♂️" : (item.gender === "Female" ? " ♀️" : " 🤖");
        var userHeader = "⛄ LV" + level + genderIcon + " 【" + (item.username || "书友") + "】：👍🏻" + (item.likes || 0);
        var contentText = String(item.content || "").replace(/<[^>]*?>/g, "").trim();

        var commentBlock = timeStr + "\n" + userHeader + "\n" + contentText;

        var replys = item.replys || [];
        for (var k = 0; k < replys.length; k++) {
            var rItem = replys[k];
            if (!rItem) continue;
            var rTime = rItem.addtime ? "[" + rItem.addtime + "]" : "";
            var rLevel = (rItem.expinfo && rItem.expinfo.level) ? rItem.expinfo.level : 1;
            var rGender = rItem.gender === "Male" ? " ♂️" : (rItem.gender === "Female" ? " ♀️" : " 🤖");
            var rHeader = "⛄ LV" + rLevel + rGender + " 【" + (rItem.username || "书友") + "】：👍🏻" + (rItem.likes || 0);
            var rContent = String(rItem.content || "").replace(/<[^>]*?>/g, "").trim();

            commentBlock += "\nㅤ    ↳ " + rTime + " " + rHeader + "\nㅤ      " + rContent;
        }

        output.push(commentBlock);
    }

    var headerTitle = "━━━━━━━━━━━━━━━━━━━━━\n☕【书友评论】 评论数：" + commentsList.length + "/" + totalCount;
    return headerTitle + "\n\n" + output.join("\n\n");
}

